import type { HTMLAttributes } from "astro/types";
import BreadcrumbItem from "./breadcrumb-item.astro";
import BreadcrumbLink from "./breadcrumb-link.astro";
import BreadcrumbList from "./breadcrumb-list.astro";
import BreadcrumbPage from "./breadcrumb-page.astro";
import BreadcrumbRoot from "./breadcrumb-root.astro";
import BreadcrumbSeparator from "./breadcrumb-separator.astro";

interface BreadcrumbPresetItem {
  label: string;
  href?: string;
  isCurrentPage?: boolean;
}

interface Props extends HTMLAttributes<"nav"> {
  /**
   * Accessible label for the breadcrumb navigation landmark.
   *
   * @defaultValue "Breadcrumb"
   */
  "aria-label"?: string;
  items?: BreadcrumbPresetItem[];
}

const { items = [], ...rest } = Astro.props;
---

<BreadcrumbRoot {...rest}>
  {
    items.length > 0 && (
      <BreadcrumbList>
        {items.map((item, index) => (
          <>
            {index > 0 && <BreadcrumbSeparator />}
            <BreadcrumbItem>
              {item.isCurrentPage ? (
                <BreadcrumbPage>{item.label}</BreadcrumbPage>
              ) : item.href ? (
                <BreadcrumbLink href={item.href}>{item.label}</BreadcrumbLink>
              ) : (
                item.label
              )}
            </BreadcrumbItem>
          </>
        ))}
      </BreadcrumbList>
    )
  }
  <slot />
</BreadcrumbRoot>

import BreadcrumbShorthand from "./breadcrumb.astro";
import BreadcrumbEllipsis from "./breadcrumb-ellipsis.astro";
import BreadcrumbItem from "./breadcrumb-item.astro";
import BreadcrumbLink from "./breadcrumb-link.astro";
import BreadcrumbList from "./breadcrumb-list.astro";
import BreadcrumbPage from "./breadcrumb-page.astro";
import BreadcrumbRoot from "./breadcrumb-root.astro";
import BreadcrumbSeparator from "./breadcrumb-separator.astro";

export const Breadcrumb = Object.assign(BreadcrumbShorthand, {
  Ellipsis: BreadcrumbEllipsis,
  Item: BreadcrumbItem,
  Link: BreadcrumbLink,
  List: BreadcrumbList,
  Page: BreadcrumbPage,
  Root: BreadcrumbRoot,
  Separator: BreadcrumbSeparator,
});

---
import { type ButtonVariantProps, buttonRecipe } from "@pisagor/recipes/button";
import type { HTMLAttributes } from "astro/types";
import Spinner from "../spinner/spinner.astro";

type Props = HTMLAttributes<"button"> & ButtonVariantProps;

const {
  clickEffect = true,
  loading = false,
  pill = false,
  size = "md",
  variant = "default",
  disabled,
  type = "button",
  class: className,
  ...rest
} = Astro.props;

const slots = buttonRecipe({ clickEffect, loading, pill, size, variant });
const content = loading ? await Astro.slots.render("default") : null;
---

<button
  {...rest}
  aria-busy={loading || undefined}
  class={slots.base({ className })}
  data-part="root"
  data-scope="button"
  data-size={size}
  data-state={loading ? "loading" : "idle"}
  data-variant={variant}
  disabled={disabled || loading}
  type={type}
>
  {
    loading ? (
      <>
        <span aria-hidden class={slots.hidden()} set:html={content!} />
        <span class={slots.srOnly()} set:html={content!} />
        <span class={slots.spinner()}>
          <Spinner aria-hidden />
        </span>
      </>
    ) : (
      <slot />
    )
  }
</button>

